```go
package main

import (
	"encoding/json"
	"fmt"
	"os"

	"github.com/segmentio/kafka-go/avro"
)

// StructToAvroSchema converts a Go struct to its corresponding Avro schema.
func StructToAvroSchema(file string) error {
	data, err := os.ReadFile(file)
	if err != nil {
		return fmt.Errorf("reading file: %w", err)
	}

	var structName string
	err = json.Unmarshal(data, &structName)
	if err != nil {
		return fmt.Errorf("unmarshalling JSON: %w", err)
	}

	// Define the field names for the Avro schema
	fields := []string{"field1", "field2", "field3"} // Example fields; you can add more as needed

	// Create an Avro schema based on the struct's field names
	schema, err := avro.NewStructSchema(fields...)
	if err != nil {
		return fmt.Errorf("creating Avro schema: %w", err)
	}

	// Write the schema to a file named 'struct.avsc'
	outPath := fmt.Sprintf("%s.avsc", structName)
	file, err := os.Create(outPath)
	if err != nil {
		return fmt.Errorf("creating output file: %w", err)
	}
	defer file.Close()

	jsonEncoder := avro.NewJSONEncoder()
	err = jsonEncoder.Write(schema)
	if err != nil {
		return fmt.Errorf("encoding schema: %w", err)
	}

	_, err = file.Write(jsonEncoder.Bytes())
	if err != nil {
		return fmt.Errorf("writing to file: %w", err)
	}

	fmt.Printf("Generated Avro schema saved to '%s'\n", outPath)
	return nil
}

func main() {
	if len(os.Args) < 3 {
		fmt.Println("Usage:", os.Args[0], "<Go Source File> <Struct Name>")
		os.Exit(1)
	}

	srcFile := os.Args[1]
	structName := os.Args[2]

	err := StructToAvroSchema(srcFile)
	if err != nil {
		fmt.Println(err)
		os.Exit(1)
	}
}
```

