import { Request, Response } from 'express';
import { RolesService } from '../services/RolesService';

class AccessGuard {
  async checkUserPermissions(req: Request, res: Response) {
    const userId = req.user.id;
    const role = await RolesService.getRoleByUserId(userId);

    // Define the allowed actions for each role (example)
    const allowedActions = {
      'admin': ['view-all-permissions', 'create-roles', 'delete-users'],
      'user': ['view-my-permissions']
    };

    if (!allowedActions[role]) {
      return res.status(403).json({ message: 'Unauthorized' });
    }

    // Check if the requested action is allowed for the current role
    const action = req.params.action || req.body.action;
    if (!allowedActions[role].includes(action)) {
      return res.status(403).json({ message: 'Action not allowed' });
    }
  }
}

export default new AccessGuard();
```

This `AccessGuard` class uses the `RolesService` to get the user's role and then checks against an allowed actions object that maps roles to lists of permitted actions. It also includes logic to handle unauthorized or forbidden requests when the user doesn't have the required role for the specified action. The guard can be used on any route middleware to enforce access control based on user roles.

